import React, {useState} from 'react'
import './App.css';
import {BrowserRouter as Router, Switch, Route, Redirect} from "react-router-dom";
import professorList from './json/professorsList.json'
import professorNisoli from './json/Nisoli-Mauro.json'
//Pages
import Home from './pages/Home.js'
import NotFoundPage from './pages/404'
import ProfessorDetails from "./components/Professor/ProfessorDetails";


function App() {

  let [professor, setProfessor] = useState("");

  console.log("hello");

  professor=professorNisoli;

  return (
      <Router>
        <Switch>
          <Route path='/' exact component={() => <Home professorList={professorList} onChangeProfessor={setProfessor} />}/>
          <Route path='/404' exact component={NotFoundPage}/>
          <Route path="/professors" exact component={() => <ProfessorDetails professor={professor} />} />
          <Redirect to="/404"/>
        </Switch>
      </Router>
  );
}

export default App;
